create table app_notifications (is_read boolean, created_at timestamp(6), id bigint generated by default as identity, user_id bigint not null, message TEXT not null, title varchar(255) not null, type enum ('APPOINTMENT_BOOKED','APPOINTMENT_CANCELLED','APPOINTMENT_REMINDER','GENERAL','GIFT_CARD_RECEIVED','LATE_ALERT','LOYALTY_EARNED','SHIFT_REMINDER','SWAP_REQUEST') not null, primary key (id));
create table appointment_services (price numeric(10,2) not null, appointment_id bigint not null, end_time timestamp(6) not null, id bigint generated by default as identity, service_id bigint not null, staff_id bigint, start_time timestamp(6) not null, status enum ('BOOKED','CANCELLED','COMPLETED','IN_PROGRESS','NO_SHOW') not null, primary key (id));
create table appointments (deposit_amount numeric(10,2), is_deposit_paid boolean, is_walk_in boolean, rebooking_nudge_sent boolean, reminder_24h_sent boolean, reminder_2h_sent boolean, total_price numeric(10,2), branch_id bigint not null, created_at timestamp(6), customer_id bigint not null, deleted_at timestamp(6), id bigint generated by default as identity, reminder_sent_at timestamp(6), updated_at timestamp(6), business_type varchar(255) not null, cancellation_reason TEXT, notes TEXT, status enum ('BOOKED','CANCELLED','COMPLETED','IN_PROGRESS','NO_SHOW') not null, primary key (id));
create table attendances (date date not null, location_lat numeric(10,8), location_lng numeric(11,8), check_in_time timestamp(6), check_out_time timestamp(6), created_at timestamp(6), id bigint generated by default as identity, shift_id bigint, staff_id bigint not null, updated_at timestamp(6), notes TEXT, status enum ('ABSENT','HALF_DAY','LATE','ON_TIME') not null, primary key (id));
create table blog_posts (created_at timestamp(6), id bigint generated by default as identity, published_at timestamp(6), updated_at timestamp(6), author varchar(255), content LONGTEXT not null, cover_image_url varchar(255), excerpt TEXT, slug varchar(255) not null unique, status varchar(255) not null, title varchar(255) not null, primary key (id));
create table branches (is_active boolean, created_at timestamp(6), deleted_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), address TEXT, business_type varchar(255), name varchar(255) not null, phone varchar(255), tax_id varchar(255), timezone varchar(255), primary key (id));
create table branch_settings (maintenance_mode boolean not null, branch_id bigint unique, id bigint generated by default as identity, brand_logo_url varchar(255), business_name varchar(255), currency varchar(255), email varchar(255), phone varchar(255), primary_color varchar(255), razorpay_key_id varchar(255), razorpay_key_secret varchar(255), stripe_public_key varchar(255), stripe_secret_key varchar(255), time_zone varchar(255), whatsapp_api_key varchar(255), whatsapp_phone_number_id varchar(255), primary key (id));
create table cart_items (quantity integer, added_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, product_id bigint not null, primary key (id));
create table cms_content_blocks (id bigint generated by default as identity, updated_at timestamp(6), updated_by bigint, block_key varchar(255) not null, content_type varchar(255) not null, content_value TEXT, page_key varchar(255) not null, primary key (id));
create table commission_earnings (amount numeric(38,2) not null, appointment_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, invoice_id bigint not null, staff_id bigint not null, primary key (id));
create table coupons (active boolean not null, discount_value numeric(10,2) not null, min_order_amount numeric(10,2), times_used integer not null, usage_limit integer, deleted_at timestamp(6), id bigint generated by default as identity, valid_from timestamp(6), valid_until timestamp(6), code varchar(50) not null unique, discount_type varchar(255) not null, primary key (id));
create table customer_notes (created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, staff_id bigint, content TEXT not null, primary key (id));
create table customer_subscriptions (remaining_balance numeric(10,2) not null, created_at timestamp(6), customer_id bigint not null, end_date timestamp(6) not null, id bigint generated by default as identity, plan_id bigint not null, start_date timestamp(6) not null, updated_at timestamp(6), status varchar(255) not null, primary key (id));
create table customers (date_of_birth date, is_primary_member boolean, total_points integer, whatsapp_opt_in boolean, created_at timestamp(6), deleted_at timestamp(6), family_group_id bigint, id bigint generated by default as identity, updated_at timestamp(6), user_id bigint unique, email varchar(255), first_name varchar(255) not null, last_name varchar(255), notes TEXT, phone varchar(255), profile_photo TEXT, referral_code varchar(255) unique, primary key (id));
create table expenses (amount numeric(10,2) not null, expense_date date not null, branch_id bigint, created_at timestamp(6), created_by bigint, id bigint generated by default as identity, supplier_id bigint, category varchar(100) not null, description TEXT, primary key (id));
create table family_groups (pool_points boolean, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(255) not null, primary key (id));
create table gift_card_transactions (amount numeric(38,2) not null, created_at timestamp(6), gift_card_id bigint not null, id bigint generated by default as identity, related_invoice_id bigint, type varchar(255) not null, primary key (id));
create table gift_cards (current_balance numeric(38,2) not null, initial_balance numeric(38,2) not null, created_at timestamp(6), deleted_at timestamp(6), expires_at timestamp(6), id bigint generated by default as identity, issued_at timestamp(6) not null, purchased_by_customer_id bigint, recipient_customer_id bigint, redeemed_at timestamp(6), sent_by_admin_id bigint, updated_at timestamp(6), source varchar(20) not null, code varchar(255) not null unique, message TEXT, recipient_email varchar(255), recipient_name varchar(255), status varchar(255) not null, primary key (id));
create table inventory (quantity integer not null, reorder_level integer, branch_id bigint not null, id bigint generated by default as identity, product_id bigint not null, primary key (id));
create table inventory_transactions (change_qty integer not null, branch_id bigint not null, created_at timestamp(6), id bigint generated by default as identity, product_id bigint not null, reference_id bigint, notes TEXT, type varchar(255) not null, primary key (id));
create table invoice_items (quantity integer not null, total_price numeric(10,2) not null, unit_price numeric(10,2) not null, id bigint generated by default as identity, invoice_id bigint not null, item_id bigint not null, item_name varchar(255) not null, item_type varchar(255) not null, primary key (id));
create table invoices (coupon_discount numeric(10,2), discount_amount numeric(10,2) not null, subtotal numeric(10,2) not null, tax_amount numeric(10,2) not null, total_amount numeric(10,2) not null, appointment_id bigint, branch_id bigint not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, updated_at timestamp(6), coupon_code varchar(50), status varchar(50) not null, primary key (id));
create table job_openings (active boolean, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), department varchar(255), description LONGTEXT not null, employment_type varchar(255), location varchar(255), title varchar(255) not null, primary key (id));
create table leave_request (from_date date, to_date date, created_at timestamp(6), id bigint generated by default as identity, staff_id bigint, updated_at timestamp(6), reason TEXT, status varchar(255), type varchar(255), primary key (id));
create table loyalty_points (points_balance integer not null, customer_id bigint not null unique, id bigint generated by default as identity, updated_at timestamp(6), primary key (id));
create table loyalty_transactions (points_delta integer not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, related_invoice_id bigint, reason varchar(255), primary key (id));
create table payments (amount numeric(10,2) not null, created_at timestamp(6), id bigint generated by default as identity, invoice_id bigint not null, payment_method varchar(255) not null, status varchar(255) not null, transaction_ref varchar(255), primary key (id));
create table payroll_records (base_salary numeric(38,2) not null, commission_earned numeric(38,2) not null, gross_pay numeric(38,2) not null, total_appointments_completed integer not null, generated_at timestamp(6), id bigint generated by default as identity, period_end timestamp(6) not null, period_start timestamp(6) not null, staff_id bigint not null, updated_at timestamp(6), status varchar(255) not null, primary key (id));
create table processed_webhooks (id bigint generated by default as identity, processed_at timestamp(6), event_id varchar(255) not null unique, provider varchar(255) not null, primary key (id));
create table products (cost numeric(10,2) not null, is_active boolean, price numeric(10,2) not null, created_at timestamp(6), deleted_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), business_type varchar(255), name varchar(255) not null, sku varchar(255) unique, type varchar(255) not null, primary key (id));
create table referrals (reward_issued boolean, completed_at timestamp(6), created_at timestamp(6), id bigint generated by default as identity, referred_customer_id bigint not null, referrer_customer_id bigint not null, code varchar(255) not null, status varchar(255) not null, primary key (id));
create table reviews (is_approved boolean not null, rating integer not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, title varchar(120), body TEXT, primary key (id));
create table roles (id bigint generated by default as identity, name varchar(255) not null unique, primary key (id));
create table services (duration_mins integer not null, is_active boolean, price numeric(10,2) not null, created_at timestamp(6), deleted_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), business_type varchar(255) not null, category varchar(255) not null, description TEXT, gender_category varchar(255), name varchar(255) not null, primary key (id));
create table shedlock (lock_until timestamp(6) not null, locked_at timestamp(6) not null, name varchar(64) not null, locked_by varchar(255) not null, primary key (name));
create table shift_swap_requests (created_at timestamp(6), id bigint generated by default as identity, requester_shift_id bigint not null, requester_staff_id bigint not null, target_shift_id bigint not null, target_staff_id bigint not null, updated_at timestamp(6), manager_notes TEXT, status enum ('APPROVED','PENDING','REJECTED') not null, primary key (id));
create table shifts (branch_id bigint not null, created_at timestamp(6), end_time timestamp(6) not null, id bigint generated by default as identity, staff_id bigint not null, start_time timestamp(6) not null, updated_at timestamp(6), status enum ('DRAFT','PUBLISHED') not null, type enum ('CUSTOM','EVENING','MORNING','NIGHT') not null, primary key (id));
create table sitting_packages (price numeric(10,2) not null, validity_days integer not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), name varchar(255) not null, primary key (id));
create table staff (base_salary numeric(10,2), commission_rate numeric(5,2), branch_id bigint not null, created_at timestamp(6), deleted_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), user_id bigint not null unique, business_type varchar(255) not null, primary key (id));
create table staff_commission_rules (commission_value numeric(38,2) not null, created_at timestamp(6), id bigint generated by default as identity, service_id bigint, staff_id bigint not null, updated_at timestamp(6), commission_type varchar(255) not null, primary key (id));
create table staff_reviews (rating integer not null, appointment_id bigint not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, staff_id bigint not null, comment TEXT, primary key (id));
create table staff_services (service_id bigint not null, staff_id bigint not null, primary key (service_id, staff_id));
create table staff_skills (is_specialty boolean, proficiency_level integer not null, created_at timestamp(6), id bigint generated by default as identity, service_id bigint not null, staff_id bigint not null, updated_at timestamp(6), primary key (id));
create table staff_note (created_at timestamp(6), id bigint generated by default as identity, staff_id bigint, updated_at timestamp(6), content TEXT, primary key (id));
create table subscription_plans (discount_rate numeric(5,2) not null, is_active boolean, price numeric(10,2) not null, total_sessions integer, validity_days integer not null, created_at timestamp(6), deleted_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), business_type varchar(255) not null, description TEXT, name varchar(255) not null, plan_type varchar(255) not null, primary key (id));
create table suppliers (active boolean not null, created_at timestamp(6), id bigint generated by default as identity, contact_phone varchar(50), address TEXT, contact_email varchar(255), name varchar(255) not null, primary key (id));
create table users (email_verified boolean, is_active boolean, branch_id bigint, created_at timestamp(6), id bigint generated by default as identity, reset_password_token_expiry timestamp(6), role_id bigint not null, updated_at timestamp(6), email varchar(255) not null unique, first_name varchar(255), last_name varchar(255), password_hash varchar(255) not null, phone varchar(255), reset_password_token varchar(255), primary key (id));
create table waitlists (preferred_date date not null, branch_id bigint not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, service_id bigint not null, status enum ('BOOKED','CANCELLED','NOTIFIED','WAITING') not null, primary key (id));
create table wallet (balance numeric(38,2) not null, created_at timestamp(6), customer_id bigint not null unique, id bigint generated by default as identity, updated_at timestamp(6), primary key (id));
create table wallet_transactions (amount numeric(38,2) not null, created_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, related_invoice_id bigint, type varchar(255) not null, primary key (id));
create table whatsapp_message_log (created_at timestamp(6), customer_id bigint, id bigint generated by default as identity, related_entity_id bigint, phone_number varchar(255) not null, related_entity_type varchar(255), status varchar(255) not null, template_name varchar(255) not null, primary key (id));
create table wishlist_items (added_at timestamp(6), customer_id bigint not null, id bigint generated by default as identity, product_id bigint not null, primary key (id));
create index idx_appointment_status on appointments (status);
create index idx_appointment_created_at on appointments (created_at);
